public String caesarCipher(String s, int k) {
    k %= 26;
    StringBuilder out = new StringBuilder(s.length());
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c >= 'a' && c <= 'z') {
            char shifted = (char) (c + k);
            if (shifted > 'z') shifted -= 26;
            out.append(shifted);
        } else if (c >= 'A' && c <= 'Z') {
            char shifted = (char) (c + k);
            if (shifted > 'Z') shifted -= 26;
            out.append(shifted);
        } else {
            out.append(c);
        }
    }
    return out.toString();
}

