def caesar_cipher(self, s: str, k: int) -> str:
    k %= 26
    out: list[str] = []
    for c in s:
        if 'a' <= c <= 'z':
            shifted = ord(c) + k
            if shifted > ord('z'):
                shifted -= 26
            out.append(chr(shifted))
        elif 'A' <= c <= 'Z':
            shifted = ord(c) + k
            if shifted > ord('Z'):
                shifted -= 26
            out.append(chr(shifted))
        else:
            out.append(c)
    return ''.join(out)

